#![allow(unreachable_code, dead_code, unused)]

use crate::Result;
use crate::codec::conversion::AppCodec;
use crate::codec::models::EventLog;
use crate::models::order::Order;
use crate::models::user::User;
use chrono::{DateTime, Utc};
use kova::Options;
use kova::dsl::func::{Count, GenerateSeries, JsonbArrayElements, JsonbEach, JsonbEachText, Unnest};
use kova::query::Select;

// Memo: Marker types designed to simulate table aliases for SRFs (Set-Returning Functions).
// Used to verify that `JustAddFrom` generated by `select_mix` / `from_mix` successfully accepts tags.
struct DateSeries;
struct KvAlias;

/// Stress Test 1: Array Expansion using Unnest
async fn compile_check_srf_unnest() -> Result<()> {
    let client = Options::from("").build()?.codec::<AppCodec>();

    // Memo: Unnest directly accepting a native Rust Vec.
    // The `IntoTableFuncArg` boundary intercepts `Vec<i32>`, treats it as an `IntoValue`,
    // and seamlessly wraps it into an `Operand` without leaking any unconstrained generics.
    let bulk_ids: Vec<i32> = vec![1, 2, 3, 4, 5];

    let _ = client
        .select_mix::<User>(Unnest(bulk_ids.clone())) // Implicit CROSS JOIN: FROM user, unnest($1)
        .columns((
            User::id,
            User::name,
            Unnest::unnest, // Extracting the single column yielded by the unnest function
        ))
        // Memo: Replacing the traditional `IN (?, ?, ?)` clause with an ultra-fast SRF join.
        .filter(User::id.eq(Unnest::unnest))
        .load_in::<(i32, String, i32)>()
        .await?;

    Ok(())
}

/// Stress Test 2: Deep JSONB Parsing & Multi-SRF Injection
async fn compile_check_srf_jsonb() -> Result<()> {
    // Memo: Plugging in AppCodec so the type system properly bounds Uuid and Url in EventLog.
    let client = Options::from("").build()?.codec::<AppCodec>();

    let _ = client
        .select_mix::<EventLog>((
            // Scenario A: Passing a `JsonbChain` into the SRF.
            // Translates to: jsonb_array_elements(metadata -> 'tags')
            JsonbArrayElements(EventLog::metadata.json_path("tags")),
            // Scenario B: Passing a raw `Column`.
            // Translates to: jsonb_each_text(metadata)
            JsonbEachText(EventLog::metadata),
        ))
        // Memo: Applying a tag to the ENTIRE composite `JustAddFrom` state.
        // This validates that our `from_mix` state transitions cleanly to `Normal` via `.tag()`.
        .tag::<KvAlias>()
        .columns((
            EventLog::id,
            // Accessing static schema fields provided by the Deref magic
            JsonbArrayElements::value,
            JsonbEachText::key.tag::<KvAlias>(),
            JsonbEachText::value.tag::<KvAlias>(),
        ))
        .filter(
            JsonbArrayElements::value.eq("urgent")
                & JsonbEachText::key.tag::<KvAlias>().eq("source")
        )
        .load_in::<(uuid::Uuid, String, String, String)>()
        .await?;

    Ok(())
}

// Stress Test 3: BI Dashboard Classic - Time Series Generation
async fn compile_check_srf_generate_series() -> Result<()> {
    let client = Options::from("").build()?.codec::<AppCodec>();

    // Memo: Polymorphic operand parameters.
    // Start/Stop are native integers, and step is optionally chained.
    let _ = client
        .select_mix::<User>(GenerateSeries(1_i32, 100_i32).step(5_i32))
        .filter(User::id.eq(GenerateSeries::generate_series))
        .load_as::<User>()
        .await?;

    // Memo: The ultimate BI reporting query.
    // Generating a continuous date skeleton and LEFT JOINing physical data (Orders) onto it.
    // Ensures that dates with zero orders are still returned in the result set.
    let _ = client
        // Start and stop are string literals; the PG engine will implicitly cast them to timestamps.
        .select_mix::<Order>(
            GenerateSeries("2026-01-01", "2026-12-31").step("1 day")
        )
        // Tagging the generated virtual sequence
        .tag::<DateSeries>()
        .left_join::<Order>(
            // Hooking the physical table's created_at to the virtual sequence value
            Order::created_at.eq(GenerateSeries::generate_series.tag::<DateSeries>())
        )
        .columns((
            GenerateSeries::generate_series.tag::<DateSeries>(),
            Count(Order::id), // Counting non-null order IDs (nulls resulting from left join will be 0)
        ))
        .group_by(GenerateSeries::generate_series.tag::<DateSeries>())
        .order_by(GenerateSeries::generate_series.tag::<DateSeries>().desc())
        .load_in::<(DateTime<Utc>, i64)>()
        .await?;

    Ok(())
}

/// Stress Test 4: Extreme Nested Subqueries inside SRFs
async fn compile_check_srf_subquery_injection() -> Result<()> {
    let client = Options::from("").build()?;

    // Memo: Validating the `Select` (Subquery) compatibility inside `IntoTableFuncArg`.
    let _ = client
        .select::<User>()
        .filter(
            User::id.in_select(
                Select::from_mix::<Order>(
                    // Crazy scenario: The SRF (jsonb_each) is fed an entire subselect!
                    // Translates to: FROM jsonb_each((SELECT metadata FROM event_log WHERE id IS NOT NULL))
                    JsonbEach(
                        Select::from::<EventLog>()
                            .columns(EventLog::metadata)
                            .filter(EventLog::id.is_not_null())
                    )
                )
                    .columns(JsonbEach::value) // The projected column resolves dynamically
            )
        )
        .load_as::<User>()
        .await?;

    Ok(())
}